import java.util.Scanner;
public class Circle {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    double r = sc.nextDouble();
    if (r < 0) {
      System.out.println("半径不能为负数");
      return;
    }
    double area = Math.PI * r * r;
    double len = 2 * Math.PI * r;
    System.out.printf("面积：%.2f%n", area);
    System.out.printf("周长：%.2f%n", len);
  }
}

import java.util.Scanner;
public class TimeFmt {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int total = sc.nextInt();
    int h = total / 3600;
    int m = total % 3600 / 60;
    int s = total % 60;
    System.out.printf("%d:%02d:%02d%n", h, m, s);
  }
}

